export const JAN_DICTIONARY = RAW.map(([jan, name, maker, category, colorName, size, code, src]) => ({
  jan, name, maker, category, colorName, size, code,
  brand: BRAND_BY_MAKER[maker] || "",
  source: typeof src === "number" ? MATUEDA_ITEM + src
    : (/^[A-Z]\d+$/.test(String(src)) ? SEKAIDO_ITEM + src : String(src)),
  verifiedAt: VERIFIED_AT,
}));

export default JAN_DICTIONARY;
